episodes.script:
function episodes(raw, context){try{
var base=(context&&typeof context.baseUrl==='string'&&context.baseUrl)?context.baseUrl:'https://javchu.com';
function abs(h){if(!h)return '';if(h.indexOf('http')===0)return h;if(h.indexOf('/')===0)return base+h;return base+'/'+h;}
if(typeof raw==='string'&&raw){
var out=[];
var re=/<div[^>]*class="playlist-hover-wrap"[^>]*data-href="([^"]+)"[^>]*>/gi;var m;
while((m=re.exec(raw))){var href=abs(m[1]);if(href&&href.indexOf('watch')>=0){var ti='';var mm=raw.slice(m.index).match(/<h4[^>]*class="video-title"[^>]*>\s*<a[^>]*>([\s\S]*?)<\/a>/i);if(mm)ti=(mm[1]||'').replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim();out.push({title:ti||'分集',url:href});}}
if(out.length)return out;
}
var du=(context&&typeof context.detailUrl==='string'&&context.detailUrl.indexOf('http')===0)?context.detailUrl:'';
if(!du&&typeof raw==='string'&&raw){var cm=raw.match(/<link[^>]+rel="canonical"[^>]+href="([^"]+)"/i)||raw.match(/property="og:url"[^>]+content="([^"]+)"/i);if(cm)du=cm[1];}
if(!du&&typeof raw==='string'&&raw){var cm2=raw.match(/href="([^"]*watch[^"]*)"/i);if(cm2)du=abs(cm2[1]);}
return du?[{title:'正片',url:du}]:[];
}catch(e){return [];}}
